 	"encoding/json"
 	"fmt"
 	"io/fs"
+	"math"
 	"net/http"
+	"strconv"
 	"strings"
 	"time"

@@ -133,6 +135,74 @@ type LostPetFormRequest struct {
 	Phone         string `json:"phone"`
 }

+type QueryParams struct {
+	Limit       int
+	Offset      int
+	Species     string
+	Status      string
+	HasGeo      bool
+	GeoPoint    domain.LocationPoint
+	RadiusMiles float64
+}
+
+func parseQueryParams(r *http.Request) QueryParams {
+	q := r.URL.Query()
+
+	limit := 20
+	if lStr := q.Get("limit"); lStr != "" {
+		if l, err := strconv.Atoi(lStr); err == nil && l >= 1 {
+			if l > 100 {
+				l = 100
+			}
+			limit = l
+		}
+	}
+
+	offset := 0
+	if oStr := q.Get("offset"); oStr != "" {
+		if o, err := strconv.Atoi(oStr); err == nil && o >= 0 {
+			offset = o
+		}
+	}
+
+	species := strings.TrimSpace(q.Get("species"))
+	status := strings.TrimSpace(q.Get("status"))
+
+	var hasGeo bool
+	var geoPoint domain.LocationPoint
+	radiusMiles := 10.0
+
+	latStr := q.Get("lat")
+	lngStr := q.Get("lng")
+	if latStr != "" && lngStr != "" {
+		lat, err1 := strconv.ParseFloat(latStr, 64)
+		lng, err2 := strconv.ParseFloat(lngStr, 64)
+		if err1 == nil && err2 == nil && !math.IsNaN(lat) && !math.IsNaN(lng) && !math.IsInf(lat, 0) && !math.IsInf(lng, 0) {
+			pt := domain.LocationPoint{Latitude: lat, Longitude: lng}
+			if pt.Validate() == nil {
+				hasGeo = true
+				geoPoint = pt
+			}
+		}
+	}
+
+	if rStr := q.Get("radiusMiles"); rStr != "" {
+		if rVal, err := strconv.ParseFloat(rStr, 64); err == nil && rVal > 0 {
+			radiusMiles = rVal
+		}
+	}
+
+	return QueryParams{
+		Limit:       limit,
+		Offset:      offset,
+		Species:     species,
+		Status:      status,
+		HasGeo:      hasGeo,
+		GeoPoint:    geoPoint,
+		RadiusMiles: radiusMiles,
+	}
+}
+
