const repo="scottdensmore/PetSpotR";
for (const n of [100,99,98,97,96,95]) {
  const [pr, comments, reactions, reviews, threads] = await Promise.all([
    tools.mcp__codex_apps__github_fetch_pr({repo_full_name:repo,pr_number:n}),
    tools.mcp__codex_apps__github_fetch_pr_comments({repo_full_name:repo,pr_number:n}),
    tools.mcp__codex_apps__github_get_pr_reactions({repo_full_name:repo,pr_number:n,per_page:100,page:1}),
    tools.mcp__codex_apps__github_list_pull_request_reviews({repo_full_name:repo,pr_number:n}),
    tools.mcp__codex_apps__github_list_pull_request_review_threads({repo_full_name:repo,pr_number:n})
  ]);
  const p=pr.structuredContent?.pull_request||{};
  const cs=comments.structuredContent?.comments||[];
  const rs=reviews.structuredContent?.reviews||[];
  const ts=threads.structuredContent?.review_threads||[];
  const reacts=reactions.structuredContent?.reactions||[];
  const botComments=cs.filter(c => (c.user?.login||"").includes("codex")).map(c=>({
    kind:c.path?"inline":(c.review?"review":"conversation"),
    created_at:c.created_at,
    review:c.review,
    path:c.path,
    body:(c.body||"").slice(0,220).replace(/\s+/g," "),
    reviewed_commit:(c.body||"").match(/Reviewed commit:\*\* `([^`]+)/)?.[1]||null
  }));
  const botReviews=rs.filter(x => (x.author?.login||"").includes("codex")).map(x=>({
    state:x.state,submitted_at:x.submitted_at,
    reviewed_commit:(x.body||"").match(/Reviewed commit:\*\* `([^`]+)/)?.[1]||null,
    body:(x.body||"").slice(0,220).replace(/\s+/g," ")
  }));
  const unresolved=ts.filter(t=>!t.is_resolved).map(t=>({outdated:t.is_outdated,path:t.path,line:t.line,first:(t.comments?.[0]?.body||"").slice(0,120).replace(/\s+/g," ")}));
  text(JSON.stringify({
    n,created_at:p.created_at,updated_at:p.updated_at,merged_at:p.merged_at,head_sha:p.head_sha,commits:p.commits,
    botComments,botReviews,reactions:reacts.map(x=>({content:x.content,user:x.user?.login,created_at:x.created_at,id:x.id})),
    thread_count:ts.length,unresolved
  }));
}

