+func (m *MemoryStore) ListState(ctx context.Context, storeName string) (map[string][]byte, error) {
+	if err := ctx.Err(); err != nil {
+		return nil, err
+	}
+
+	m.mu.RLock()
+	defer m.mu.RUnlock()
+
+	res := make(map[string][]byte)
+	storeMap, exists := m.items[storeName]
+	if !exists {
+		return res, nil
+	}
+
+	for k, v := range storeMap {
+		res[k] = bytes.Clone(v)
+	}
+	return res, nil
